        error: {
          name: event.data.error.name ?? 'Error',
          code: event.data.error.code ?? 'unknown',
          ...(event.data.error.reason === undefined ? {} : { reason: event.data.error.reason }),
        },
      }),
    ...(ref === undefined ? {} : { resultRef: ref.hash }),
  }
}
